#!/usr/bin/env Rscript
# Auto-generated by vmbdiet.maaslin - MaAsLin 3 model for the gut-vagina axis.
# install once: BiocManager::install("maaslin3")
suppressMessages(library(maaslin3))

features <- read.delim("features.tsv", row.names = 1, check.names = FALSE)
metadata <- read.delim("metadata.tsv", row.names = 1, check.names = FALSE)

# Repeated measures: each participant contributes rectal + vaginal samples across timepoints,
# so the random intercept (1 | participant) absorbs the within-host correlation.
fit <- maaslin3(
    input_data        = features,
    input_metadata    = metadata,
    output            = "maaslin3_out",
    formula           = ~ fiber + animal_protein + age + body_site + (1 | participant),
    normalization     = "TSS",
    transform         = "LOG",
    correction        = "BH",
    augment           = TRUE,
    standardize       = TRUE,                        # per-SD effects, comparable across diet variables
    median_comparison_abundance = TRUE,              # MaAsLin 3 abundance null at the median
    cores             = 4
)
# Outputs: maaslin3_out/significant_results.tsv  (abundance + prevalence associations, BH-corrected)
